378→export default function PricingPage() {
379→  const { subscription } = useLoaderData<typeof loader>();
380→  const fetcher = useFetcher<typeof action>();
381→  const navigate = useNavigate();
382→  const shopify = useAppBridge();
383→
384→  const [isAnnual, setIsAnnual] = useState(
385→    subscription.billingInterval === "annual",
386→  );
387→  const [loadingPlan, setLoadingPlan] = useState<string | null>(null);
388→  const [cancelModalOpen, setCancelModalOpen] = useState(false);
389→
390→  const data = fetcher.data;
391→  const isFetching = fetcher.state !== "idle";
392→
393→  // Toast for success, Banner for errors (errors must not auto-dismiss)
394→  useEffect(() => {
395→    if (!isFetching) setLoadingPlan(null);
396→    if (data && "message" in data && data.message) {
397→      shopify.toast.show(data.message as string);
398→    }
399→  }, [data, isFetching, shopify]);
400→
401→  const actionError =
402→    data && "error" in data && data.error ? (data.error as string) : null;
403→
404→  const handleSubscribe = useCallback(
405→    (planName: string) => {
406→      setLoadingPlan(planName);
407→      const fd = new FormData();
408→      fd.set("intent", "subscribe");
409→      fd.set("plan", planName);
410→      fetcher.submit(fd, { method: "POST" });
411→    },
412→    [fetcher],
413→  );
414→
415→  const handleConfirmCancel = useCallback(() => {
416→    setCancelModalOpen(false);
417→    setLoadingPlan("cancel");
418→    const fd = new FormData();
419→    fd.set("intent", "cancel");
420→    fetcher.submit(fd, { method: "POST" });
421→  }, [fetcher]);
422→
423→  const currentTier = subscription.planTier;
424→  const currentPlanName =
425→    PLANS_DATA[currentTier as keyof typeof PLANS_DATA]?.name ?? "Free";
426→
427→  // Suggest next tier for upgrade banner
428→  const nextTier =
429→    currentTier === "free"
430→      ? "starter"
431→      : currentTier === "starter"
432→        ? "pro"
433→        : null;
434→
435→  return (
436→    <Page
437→      title="Pricing"
438→      subtitle="Choose the plan that's right for your store"
439→      backAction={{ onAction: () => navigate("/app") }}
440→    >
441→      <Box paddingBlockEnd="1600">
442→      <Layout>
443→        {actionError && (
444→          <Layout.Section>
445→            <Banner tone="critical" title="Billing error">
446→              <Text as="p" variant="bodyMd">{actionError}</Text>
447→            </Banner>
448→          </Layout.Section>
449→        )}
450→        <Layout.Section>
451→          <BlockStack gap="600">
452→
453→            {/* Current plan status */}
454→            {nextTier ? (
455→              <Banner
456→                tone="info"
457→                title={`You're on the ${currentPlanName} plan`}
458→                action={{
459→                  content: `Upgrade to ${PLANS_DATA[nextTier].name}`,
460→                  onAction: () => {
461→                    const plan = isAnnual
462→                      ? PLANS_DATA[nextTier].shopifyPlanAnnual
463→                      : PLANS_DATA[nextTier].shopifyPlanMonthly;
464→                    if (plan) handleSubscribe(plan);
465→                  },
466→                }}
467→              >
468→                <Text as="p" variant="bodyMd">
469→                  {currentTier === "free"
470→                    ? "You have up to 20 allowed zip codes and basic widget access. Upgrade to unlock more features."
471→                    : "Upgrade to Pro for unlimited zip codes, blocked areas, full waitlist, and more."}
472→                </Text>
473→              </Banner>
474→            ) : (
475→              <Banner tone="success" title={`You're on the ${currentPlanName} plan`}>
476→                <InlineStack gap="200" blockAlign="center">
477→                  <Badge tone="success">Active</Badge>
478→                  <Text as="p" variant="bodyMd">
479→                    {currentTier === "ultimate"
480→                      ? "You have full access to all features including VIP support and API access."
481→                      : "You have unlimited zip codes, blocked areas, delivery rules, and more."}
482→                  </Text>
483→                </InlineStack>
484→              </Banner>
485→            )}
486→
487→            {/* Action feedback banners */}
488→            {data && "success" in data && data.success && (
489→              <Banner tone="success">
490→                {data && "message" in data
491→                  ? String(data.message)
492→                  : "Plan updated successfully."}
493→              </Banner>
494→            )}
495→
496→            {/* Billing toggle */}
497→            <BlockStack gap="200" inlineAlign="center">
498→              <ButtonGroup variant="segmented">
499→                <Button
500→                  pressed={!isAnnual}
501→                  onClick={() => setIsAnnual(false)}
502→                >
503→                  Monthly
504→                </Button>
505→                <Button
506→                  pressed={isAnnual}
507→                  onClick={() => setIsAnnual(true)}
508→                >
509→                  Annual · Save up to 38%
510→                </Button>
511→              </ButtonGroup>
512→              {isAnnual && (
513→                <Badge tone="success">You save up to 38% per year</Badge>
514→              )}
515→            </BlockStack>
516→
517→            {/* Plan cards — 4 columns */}
518→            <InlineGrid columns={{ xs: 1, sm: 2, md: 4 }} gap="400">
519→              {(
520→                Object.values(
521→                  PLANS_DATA,
522→                ) as (typeof PLANS_DATA)[keyof typeof PLANS_DATA][]
523→              ).map((plan) => (
524→                <PlanCard
525→                  key={plan.id}
526→                  plan={plan}
527→                  isAnnual={isAnnual}
528→                  currentTier={currentTier}
529→                  onSubscribe={handleSubscribe}
530→                  onRequestCancel={() => setCancelModalOpen(true)}
531→                  loadingPlan={loadingPlan}
532→                />
533→              ))}
534→            </InlineGrid>
535→
536→            {/* Trial footnote */}
537→            {(currentTier === "free" || currentTier === "starter") && (
538→              <Text
539→                as="p"
540→                variant="bodySm"
541→                tone="subdued"
